  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals with multiple lines and mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const line1Subtotal = 85000;
  const line2Subtotal = 3700;
  const line1VAT = Math.round(85000 * 21 / 100);
  const line2VAT = Math.round(3700 * 9 / 100);

  assert.equal(totals.subtotal, 88700);
  assert.equal(totals.vat, line1VAT + line2VAT);
  assert.equal(totals.total, 88700 + line1VAT + line2VAT);
});

